function EmployeeModal({ form, setForm, onSubmit, onClose }: { form: { name: string; email: string; loginId: string; password: string; organization: string; role: string }; setForm: React.Dispatch<React.SetStateAction<{ name: string; email: string; loginId: string; password: string; organization: string; role: string }>>; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void; onClose: () => void }) {
  const update = (field: keyof typeof form, value: string) => setForm((current) => ({ ...current, [field]: value }))
  return <div className="modal-backdrop employee-modal-backdrop"><section className="employee-modal-3d" role="dialog" aria-modal="true" aria-labelledby="add-employee-title">
    <div className="employee-modal-art"><div className="art-orbit orbit-a"/><div className="art-orbit orbit-b"/><div className="art-cube"><Users size={31}/></div><span className="art-chip chip-one"><Check size={13}/> VERIFIED</span><span className="art-chip chip-two"><KeyRound size={13}/> ROOT USER</span><div className="art-caption"><span className="eyebrow">WORKSPACE ACCESS</span><b>Bring your team<br/>into SmartIAM.</b><small>Only the permissions they need.<br/>Reviewed access stays with Security.</small></div></div>
    <div className="employee-form-side"><div className="employee-modal-heading"><div><span className="eyebrow">ORGANIZATION ADMIN</span><h2 id="add-employee-title">Add employee</h2><p>Create a Root User account for your organization.</p></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close add employee"><X size={19}/></button></div>
      <form className="employee-form" onSubmit={onSubmit}>
        <label className="form-field"><span>Employee full name</span><input required autoComplete="name" value={form.name} onChange={(event) => update('name', event.target.value)} placeholder="e.g. Ananya Rao"/></label>
        <label className="form-field"><span>Work email</span><input required type="email" autoComplete="email" value={form.email} onChange={(event) => update('email', event.target.value)} placeholder="name@company.com"/></label>
        <div className="employee-form-grid"><label className="form-field"><span>Login ID</span><input required autoComplete="username" value={form.loginId} onChange={(event) => update('loginId', event.target.value)} placeholder="e.g. ananya.rao"/></label><label className="form-field"><span>Temporary password</span><input required type="password" minLength={8} autoComplete="new-password" value={form.password} onChange={(event) => update('password', event.target.value)} placeholder="At least 8 characters"/></label></div>
        <label className="form-field"><span>Organization</span><input required value={form.organization} onChange={(event) => update('organization', event.target.value)} placeholder="Company name"/></label>
        <label className="form-field"><span>Role</span><select value={form.role} onChange={(event) => update('role', event.target.value)}><option value="Root User">Root User · Employee</option></select><small className="role-field-help">Main Admins can create employee accounts only. Security Team access is provisioned separately.</small></label>
        <div className="employee-permission-note"><ShieldCheck size={16}/><span><b>Access stays approval-based.</b> Adding an employee creates a workspace profile; it does not grant AWS permissions.</span></div>
        <div className="employee-modal-actions"><button type="button" className="button button-outline" onClick={onClose}>Cancel</button><button type="submit" className="button button-primary"><Plus size={15}/> Add employee</button></div>
      </form>
    </div>
  </section></div>
}
